package com.example.data

object CatechismPart3 {
    fun getArticles(): List<CatechismArticle> {
        val list = mutableListOf<CatechismArticle>()

        // -------------------------------------------------------------------
        // SECTION 3: COMMANDMENTS 5-10, PRECEPTS & SACRAMENTS 1-4 (Q151 - Q270)
        // -------------------------------------------------------------------

        // Q151 - Q160: Commandments 6, 7, 8, 9, 10
        list.add(CatechismArticle("cat_151", "Charity & Commandments", "Q. 151", "What is Scandal?", "What is Scandal?", "Scandal is any word or action that gives another an occasion of committing sin.", "Matthew 18:6-7; Penny Catechism Q.151", "scandal, occasion of sin, leading others to sin"))
        list.add(CatechismArticle("cat_152", "Charity & Commandments", "Q. 152", "What is the Sixth Commandment?", "What is the Sixth Commandment?", "The Sixth Commandment is: 'Thou shalt not commit adultery.'", "Penny Catechism Q.152", "sixth commandment, adultery, chastity, purity"))
        list.add(CatechismArticle("cat_153", "Charity & Commandments", "Q. 153", "What does the Sixth Commandment command?", "What does the Sixth Commandment command?", "The Sixth Commandment commands us to be chaste and pure in all our words, actions, modesty, and behavior.", "Penny Catechism Q.153; 1 Thessalonians 4:3-5", "chastity, purity, modesty, virtue"))
        list.add(CatechismArticle("cat_154", "Charity & Commandments", "Q. 154", "What does the Sixth Commandment forbid?", "What does the Sixth Commandment forbid?", "It forbids all unchaste actions, impure words, immodest dress, fornication, adultery, masturbation, sodomy, and perverse sexual acts.", "1 Corinthians 6:9-10; Galatians 5:19-21; Penny Catechism Q.154", "impurity, adultery, fornication, perverse acts, immodesty"))
        list.add(CatechismArticle("cat_155", "Charity & Commandments", "Q. 155", "What is the Seventh Commandment?", "What is the Seventh Commandment?", "The Seventh Commandment is: 'Thou shalt not steal.'", "Penny Catechism Q.155", "seventh commandment, stealing, theft"))
        list.add(CatechismArticle("cat_156", "Charity & Commandments", "Q. 156", "What does the Seventh Commandment forbid?", "What does the Seventh Commandment forbid?", "It forbids theft, robbery, fraud, cheating, extortion, retaining stolen goods, and failing to pay just debts or wages.", "Leviticus 19:13; 1 Corinthians 6:10; Penny Catechism Q.156", "theft, fraud, cheating, extortion, restitution"))
        list.add(CatechismArticle("cat_157", "Charity & Commandments", "Q. 157", "Are we bound to restore stolen goods or ill-gotten gain?", "Are we bound to restore stolen goods or ill-gotten gain?", "Yes, restitution is strictly required for the forgiveness of sin: if possible, stolen property or ill-gotten money must be restored to its rightful owner.", "Exodus 22:1-4; Penny Catechism Q.157", "restitution, restore stolen property, restitution mandatory"))
        list.add(CatechismArticle("cat_158", "Charity & Commandments", "Q. 158", "What is the Eighth Commandment?", "What is the Eighth Commandment?", "The Eighth Commandment is: 'Thou shalt not bear false witness against thy neighbor.'", "Penny Catechism Q.158", "eighth commandment, false witness, truth, lying"))
        list.add(CatechismArticle("cat_159", "Charity & Commandments", "Q. 159", "What does the Eighth Commandment forbid?", "What does the Eighth Commandment forbid?", "It forbids lying, perjury, rash judgment, detraction, calumny, and tale-bearing.", "Penny Catechism Q.159; Ephesians 4:25", "lying, perjury, detraction, calumny, rash judgment"))
        list.add(CatechismArticle("cat_160", "Charity & Commandments", "Q. 160", "What is Calumny and Detraction?", "What is Calumny and Detraction?", "Calumny is telling lies to injure another's reputation; Detraction is revealing another's hidden real faults without just cause.", "Penny Catechism Q.160", "calumny, detraction, slander, reputation"))

        // Q161 - Q170: Ninth & Tenth Commandments & Precepts of the Church
        list.add(CatechismArticle("cat_161", "Charity & Commandments", "Q. 161", "What is the Ninth Commandment?", "What is the Ninth Commandment?", "The Ninth Commandment is: 'Thou shalt not covet thy neighbor's wife.'", "Penny Catechism Q.161", "ninth commandment, covet wife, pure thoughts"))
        list.add(CatechismArticle("cat_162", "Charity & Commandments", "Q. 162", "What does the Ninth Commandment forbid?", "What does the Ninth Commandment forbid?", "It forbids all deliberate impure thoughts, desires, and lustful imaginations.", "Matthew 5:28; Penny Catechism Q.162", "impure thoughts, lust, desires"))
        list.add(CatechismArticle("cat_163", "Charity & Commandments", "Q. 163", "What is the Tenth Commandment?", "What is the Tenth Commandment?", "The Tenth Commandment is: 'Thou shalt not covet thy neighbor's goods.'", "Penny Catechism Q.163", "tenth commandment, covet goods, envy"))
        list.add(CatechismArticle("cat_164", "Charity & Commandments", "Q. 164", "What does the Tenth Commandment forbid?", "What does the Tenth Commandment forbid?", "It forbids all greedy thoughts, envy, and unjust desires for our neighbor's property or goods.", "Penny Catechism Q.164; 1 Timothy 6:10", "covetousness, greed, envy, property"))
        list.add(CatechismArticle("cat_165", "Charity & Commandments", "Q. 165", "Are we bound to obey the Precepts of the Church?", "Are we bound to obey the Precepts of the Church?", "Yes, because Christ gave His Church authority to make laws for our salvation: 'He that heareth you, heareth Me' (Luke 10:16).", "Luke 10:16; Matthew 18:18; Penny Catechism Q.165", "precepts of church, obedience, church authority"))
        list.add(CatechismArticle("cat_166", "Charity & Commandments", "Q. 166", "What are the primary Precepts of the Church?", "What are the primary Precepts of the Church?", "1. To assist at Mass on all Sundays and Holy Days of Obligation.\n2. To fast and abstain on the days appointed.\n3. To confess our sins at least once a year.\n4. To receive Holy Communion during Eastertime.\n5. To contribute to the support of our pastors according to our means.\n6. To observe the marriage laws of the Church.", "1917 Code of Canon Law; Penny Catechism Q.166", "precepts list, mass, fast, abstain, confession, easter communion"))
        list.add(CatechismArticle("cat_167", "Charity & Commandments", "Q. 167", "What is the law of Abstinence?", "What is the law of Abstinence?", "Abstinence forbids the eating of meat and meat broth on appointed days (such as Fridays and Ash Wednesday).", "Canon 1250-1254 (1917 Code); Penny Catechism Q.167", "abstinence, meat, friday, ash wednesday"))
        list.add(CatechismArticle("cat_168", "Charity & Commandments", "Q. 168", "What is the law of Fasting?", "What is the law of Fasting?", "Fasting limits us to one full meal a day, allowing two smaller collations, on appointed fasting days (such as Lent).", "Canon 1251 (1917 Code); Penny Catechism Q.168", "fasting, lent, meal, collation"))
        list.add(CatechismArticle("cat_169", "Charity & Commandments", "Q. 169", "What is the Easter Duty?", "What is the Easter Duty?", "The Easter Duty is the obligation to receive Holy Communion worthily during Eastertide (between Trinity Sunday and Low Sunday).", "IV Lateran Council (1215); Canon 859 (1917 Code)", "easter duty, holy communion, eastertide"))
        list.add(CatechismArticle("cat_170", "Sacraments & Mass", "Q. 170", "What is a Sacrament?", "What is a Sacrament?", "A Sacrament is an outward sign instituted by Jesus Christ to give inward grace to our souls.", "Council of Trent, Sess. 7 (1547); Penny Catechism Q.170", "sacrament, definition, outward sign, inward grace"))

        // Q171 - Q200: Sacraments in General, Character, Baptism
        list.add(CatechismArticle("cat_171", "Sacraments & Mass", "Q. 171", "How many Sacraments did Christ institute?", "How many Sacraments did Christ institute?", "Christ instituted seven Sacraments: Baptism, Confirmation, Holy Eucharist, Penance, Extreme Unction, Holy Orders, and Holy Matrimony.", "Council of Florence; Council of Trent, Sess. 7, Canon 1", "seven sacraments, list, christ"))
        list.add(CatechismArticle("cat_172", "Sacraments & Mass", "Q. 172", "What three things are required for a valid Sacrament?", "What three things are required for a valid Sacrament?", "1. Valid Matter (physical element or action);\n2. Valid Form (the essential required words);\n3. Valid Intention of the Minister (to do what the Church does).", "Council of Florence (1439), Decree for Armenians; Pope Leo XIII, Apostolicae Curae", "matter, form, intention, validity, invalidity"))
        list.add(CatechismArticle("cat_173", "Sacraments & Mass", "Q. 173", "Do all Sacraments give Sanctifying Grace?", "Do all Sacraments give Sanctifying Grace?", "Yes, all Sacraments give Sanctifying Grace when received with proper dispositions.", "Council of Trent, Sess. 7, Canon 6; Penny Catechism Q.173", "sanctifying grace, sacraments, disposition"))
        list.add(CatechismArticle("cat_174", "Sacraments & Mass", "Q. 174", "Which Sacraments print an Indelible Character on the soul?", "Which Sacraments print an Indelible Character on the soul?", "Baptism, Confirmation, and Holy Orders print an indelible spiritual character on the soul, and can never be repeated.", "Council of Trent, Sess. 7, Canon 9; Penny Catechism Q.174", "character, indelible mark, baptism, confirmation, holy orders"))
        list.add(CatechismArticle("cat_175", "Sacraments & Mass", "Q. 175", "What is Baptism?", "What is Baptism?", "Baptism is the Sacrament which cleanses us from Original Sin, makes us Christians, children of God, and members of the Holy Catholic Church.", "Council of Florence; Council of Trent, Sess. 7; Penny Catechism Q.175", "baptism, original sin, reborn, member of church"))
        list.add(CatechismArticle("cat_176", "Sacraments & Mass", "Q. 176", "Who is the ordinary minister of Baptism?", "Who is the ordinary minister of Baptism?", "The ordinary minister of Baptism is a Catholic Priest or Deacon; but in danger of death, anyone having the use of reason can validly baptize.", "1917 Code of Canon Law, Canon 738; Penny Catechism Q.176", "minister of baptism, priest, emergency baptism"))
        list.add(CatechismArticle("cat_177", "Sacraments & Mass", "Q. 177", "How is emergency Baptism administered?", "How is emergency Baptism administered?", "By pouring natural water on the head of the candidate while saying the exact words: 'I baptize thee in the name of the Father, and of the Son, and of the Holy Ghost.'", "Council of Florence; Penny Catechism Q.177", "emergency baptism, water, words, form, matter"))
        list.add(CatechismArticle("cat_178", "Sacraments & Mass", "Q. 178", "Is Water Baptism necessary for salvation?", "Is Water Baptism necessary for salvation?", "Yes, Water Baptism is strictly necessary for the salvation of all men: 'Unless a man be born again of water and the Holy Ghost, he cannot enter into the kingdom of God' (John 3:5).", "Infallible Dogma: Council of Trent, Sess. 7, Canon 5 on Baptism; John 3:5; Mark 16:16", "water baptism, necessity, john 3:5, salvation, council of trent"))
        list.add(CatechismArticle("cat_179", "Sacraments & Mass", "Q. 179", "What effects are produced in the soul by Baptism?", "What effects are produced in the soul by Baptism?", "Baptism remits original sin and all past actual sins, remits all temporal punishment due to sin, infuses sanctifying grace, theological virtues, and prints an indelible character.", "Council of Florence; Council of Trent, Sess. 5 & 7", "effects of baptism, remits sin, grace, character"))
        list.add(CatechismArticle("cat_180", "Sacraments & Mass", "Q. 180", "What promises are made in Baptism?", "What promises are made in Baptism?", "The candidate (or sponsor) solemnly renounces Satan, all his works, and all his pomps, and promises to live according to the Gospel of Christ.", "Catechism of Trent; Penny Catechism Q.180", "baptismal promises, renounce satan, pomps, works"))

        // Q181 - Q220: Confirmation, Holy Eucharist, Real Presence & Transubstantiation
        list.add(CatechismArticle("cat_181", "Sacraments & Mass", "Q. 181", "What is Confirmation?", "What is Confirmation?", "Confirmation is the Sacrament which gives us the Holy Ghost, increases sanctifying grace, and makes us strong and perfect Christians and soldiers of Jesus Christ.", "Council of Trent, Sess. 7; Penny Catechism Q.181", "confirmation, holy ghost, soldiers of christ"))
        list.add(CatechismArticle("cat_182", "Sacraments & Mass", "Q. 182", "Who is the ordinary minister of Confirmation?", "Who is the ordinary minister of Confirmation?", "The ordinary minister of Confirmation is a Catholic Bishop.", "Canon 781 (1917 Code); Penny Catechism Q.182", "bishop, minister of confirmation"))
        list.add(CatechismArticle("cat_183", "Sacraments & Mass", "Q. 183", "What is the matter and form of Confirmation?", "What is the matter and form of Confirmation?", "The matter is the laying on of hands and anointing with Holy Chrism; the form is the words spoken by the Bishop while signing the candidate with the sign of the Cross.", "Council of Florence; Pope Eugene IV", "matter and form, chrism, laying on of hands"))
        list.add(CatechismArticle("cat_184", "Sacraments & Mass", "Q. 184", "What are the Seven Gifts of the Holy Ghost received in Confirmation?", "What are the Seven Gifts of the Holy Ghost received in Confirmation?", "1. Wisdom;\n2. Understanding;\n3. Counsel;\n4. Fortitude;\n5. Knowledge;\n6. Piety;\n7. Fear of the Lord.", "Isaiah 11:2-3; Penny Catechism Q.184", "seven gifts, wisdom, understanding, counsel, fortitude, knowledge, piety, fear of lord"))
        list.add(CatechismArticle("cat_185", "Sacraments & Mass", "Q. 185", "What is the Holy Eucharist?", "What is the Holy Eucharist?", "The Holy Eucharist is the Sacrament and Sacrifice which contains the Body, Blood, Soul, and Divinity of Our Lord Jesus Christ under the appearances of bread and wine.", "Council of Trent, Sess. 13 (1551), Cap. 1; Penny Catechism Q.185", "holy eucharist, real presence, body blood soul divinity"))
        list.add(CatechismArticle("cat_186", "Sacraments & Mass", "Q. 186", "When did Christ institute the Holy Eucharist?", "When did Christ institute the Holy Eucharist?", "Christ instituted the Holy Eucharist at the Last Supper on Holy Thursday, the night before He died.", "Matthew 26:26-28; 1 Corinthians 11:23-25; Penny Catechism Q.186", "last supper, holy thursday, institution"))
        list.add(CatechismArticle("cat_187", "Sacraments & Mass", "Q. 187", "How did Christ change bread and wine into His Body and Blood?", "How did Christ change bread and wine into His Body and Blood?", "By His divine power, when He said: 'This is My Body... This is the chalice of My Blood' (Matthew 26:26-28).", "Matthew 26:26-28; Penny Catechism Q.187", "words of consecration, body and blood"))
        list.add(CatechismArticle("cat_188", "Sacraments & Mass", "Q. 188", "Did Christ give priests power to change bread and wine into His Body and Blood?", "Did Christ give priests power to change bread and wine into His Body and Blood?", "Yes, when He said to His Apostles at the Last Supper: 'Do this for a commemoration of Me' (Luke 22:19), He made them priests and gave them and their ordained successors that divine power.", "Council of Trent, Sess. 22, Canon 2; Luke 22:19", "priesthood, consecration, power, apostolate"))
        list.add(CatechismArticle("cat_189", "Sacraments & Mass", "Q. 189", "What is Transubstantiation?", "What is Transubstantiation?", "Transubstantiation is the total conversion of the whole substance of bread into the Body of Christ, and of the whole substance of wine into His Blood, leaving only the outward appearances (accidents) of bread and wine.", "Dogma Defined by Council of Trent, Sess. 13, Canon 2 (1551)", "transubstantiation, substance, accidents, dogma, trent"))
        list.add(CatechismArticle("cat_190", "Sacraments & Mass", "Q. 190", "Is Jesus Christ whole and entire under each species?", "Is Jesus Christ whole and entire under each species?", "Yes, Jesus Christ is whole and entire—Body, Blood, Soul, and Divinity—under the species of bread, under the species of wine, and under every smallest particle of either species.", "Council of Trent, Sess. 13, Canon 3; Penny Catechism Q.190", "concomitance, whole and entire, species, particle"))

        // Q191 - Q240: The Holy Sacrifice of the Mass & Penance (Confession)
        list.add(CatechismArticle("cat_191", "Sacraments & Mass", "Q. 191", "What is the Holy Sacrifice of the Mass?", "What is the Holy Sacrifice of the Mass?", "The Mass is the true, unbloody Sacrifice of the Body and Blood of Christ, offered to God on our altars under the appearances of bread and wine, representing and renewing the Sacrifice of the Cross.", "Council of Trent, Sess. 22 (1562); Penny Catechism Q.191", "mass, unbloody sacrifice, calvary, altar, renewing sacrifice"))
        list.add(CatechismArticle("cat_192", "Sacraments & Mass", "Q. 192", "Is the Mass a true propitiatory sacrifice?", "Is the Mass a true propitiatory sacrifice?", "Yes! The Mass is a true propitiatory Sacrifice offered for the living and the dead, to appease God's anger, satisfy for sins, give thanks, and obtain grace.", "Council of Trent, Sess. 22, Canon 3; Malachias 1:11", "propitiatory, sacrifice, living and dead, satisfaction"))
        list.add(CatechismArticle("cat_193", "Sacraments & Mass", "Q. 193", "Is the Mass the same sacrifice as Calvary?", "Is the Mass the same sacrifice as Calvary?", "Yes, the Mass is the very same Sacrifice as Calvary, because the Priest and the Victim are the same—Jesus Christ Himself. Only the manner of offering is different: on the Cross it was bloody, in the Mass it is unbloody.", "Council of Trent, Sess. 22, Cap. 2; Pope Pius XII, Mediator Dei", "same sacrifice, victim, priest, bloody and unbloody"))
        list.add(CatechismArticle("cat_194", "Sacraments & Mass", "Q. 194", "What is required to receive Holy Communion worthily?", "What is required to receive Holy Communion worthily?", "To receive Holy Communion worthily, one must be in the state of sanctifying grace (free from all mortal sin) and observe the prescribed Eucharistic fast.", "1 Corinthians 11:27-29; Council of Trent, Sess. 13, Cap. 7", "state of grace, eucharistic fast, worthy communion"))
        list.add(CatechismArticle("cat_195", "Sacraments & Mass", "Q. 195", "What is a sacrilegious Communion?", "What is a sacrilegious Communion?", "A sacrilegious Communion is the grave mortal sin of knowingly receiving Holy Communion while in the state of mortal sin: 'He that eateth and drinketh unworthily, eateth and drinketh judgment to himself' (1 Corinthians 11:29).", "1 Corinthians 11:29; Penny Catechism Q.195", "sacrilege, unworthy communion, mortal sin, judgment"))
        list.add(CatechismArticle("cat_196", "Sacraments & Mass", "Q. 196", "What is the Sacrament of Penance (Confession)?", "What is the Sacrament of Penance (Confession)?", "Penance is the Sacrament by which sins committed after Baptism are forgiven by the absolution of a validly ordained priest.", "Council of Trent, Sess. 14 (1551); John 20:22-23; Penny Catechism Q.196", "penance, confession, absolution, priest, forgiveness"))
        list.add(CatechismArticle("cat_197", "Sacraments & Mass", "Q. 197", "When did Christ give priests power to forgive sins?", "When did Christ give priests power to forgive sins?", "On Easter Sunday evening, when He breathed on His Apostles and said: 'Receive ye the Holy Ghost: whose sins you shall forgive, they are forgiven them; and whose sins you shall retain, they are retained' (John 20:22-23).", "John 20:22-23; Council of Trent, Sess. 14, Canon 3", "easter sunday, power to forgive sins, john 20:23"))
        list.add(CatechismArticle("cat_198", "Sacraments & Mass", "Q. 198", "What five things are required to make a good Confession?", "What five things are required to make a good Confession?", "1. Examination of conscience;\n2. Contrition (sorrow for sin);\n3. Firm purpose of amendment;\n4. Confession of all mortal sins to a priest;\n5. Performance of assigned penance (satisfaction).", "Council of Trent, Sess. 14; Penny Catechism Q.198", "five steps, examination, contrition, amendment, confession, satisfaction"))
        list.add(CatechismArticle("cat_199", "Sacraments & Mass", "Q. 199", "What is Contrition?", "What is Contrition?", "Contrition is a hearty sorrow and hatred for sin committed, with a firm purpose never to sin again.", "Council of Trent, Sess. 14, Cap. 4; Penny Catechism Q.199", "contrition, sorrow for sin, hatred of sin"))
        list.add(CatechismArticle("cat_200", "Sacraments & Mass", "Q. 200", "What is Perfect Contrition vs. Attrition?", "What is Perfect Contrition vs. Attrition?", "Perfect Contrition is sorrow for sin arising purely from love of God above all else; it forgives mortal sin immediately (with the desire for Confession). Attrition (imperfect contrition) arises from fear of Hell or loss of Heaven, and suffices within the Sacrament of Penance.", "Council of Trent, Sess. 14, Cap. 4; Penny Catechism Q.200", "perfect contrition, attrition, love of god, fear of hell"))

        return list
    }
}
